L8_1 = "나의 최고 기록"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_GAUNTLET_POPUP_LEAGUEINFO_INFO"
L9_1 = "· 매주 일요일 밤 11시에 주간 랭크가 마감됩니다.\n· 지난 주의 성적에 따라 보상을 지급합니다.\n· 월요일 04시에 주간 리그가 시작됩니다."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_PF_GAUNTLET_SEASON"
L10_1 = "시 즌"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_PF_GAUNTLET_WEEKLY"
L11_1 = "주 간"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_PF_GAUNTLET_HELP"
L12_1 = "도움말"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_PF_GAUNTLET_POPUP_LEAGUEINFO_INFO_FINALWEEK"
L13_1 = "시즌 마지막 주에는 주간 보상 대신 시즌 보상이 지급됩니다."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_PF_GAUNTLET_POPUP_LEAGUEINFO_INFO2"
L14_1 = "· 장비, 레벨업, 강화로 얻는 능력치는 일부만 적용됩니다.\n· 자신과 비슷한 승점의 유저와 매칭됩니다.\n· 자신보다 높은 승점의 유저에게 승리하면 승점을 많이 얻고, 질 경우 적게 잃습니다.\n· 자신보다 낮은 승점의 유저에게 승리하면 승점을 적게 얻고, 질 경우 많이 잃습니다.\n· 승점을 일정 이상 얻으면 상위 리그로 올라갈 수 있습니다.\n· 일부 리그에서, 해당 리그의 승점보다 100점 이하로 떨어지면 강등될 수 있습니다.\n· 상위 리그에서는 조건을 달성하지 못하면 경고 없이 강등될 수 있습니다.\n· 랭크전에서 고의적인 패배로 점수를 지나치게 떨어뜨린 경우, 매칭 기준 점수가 일정 점수 이하로 하락되지 않게 보정이 적용됩니다.\n"
L12_1[1] = L13_1
L12_1[2] = L14_1
