L15_1 = "SI_PF_FRIEND_MENTORING_INFO_TEXT"
L16_1 = "<size=40>추천 대상을 등록하세요!</size>\n\n회사 레벨 25 이하인 경우 추천 대상 등록이 가능합니다.\n추천 대상 등록 후 주어진 미션을 모두 달성하면 나와 추천 대상 모두 보상을 얻습니다.\n\n회사 레벨이 25보다 높으면 추천 대상을 등록할 수 없으며,\n<color=#ffc400>3일 이상 미접속 시, 추천 대상으로 부터 추천인을 해제 당할 수 있습니다.\n회사 레벨 26 이상인 상태에서 해제 당할 경우, 추천 대상 재등록이 불가능하며 보상을 획득 할 수 없습니다.</color>"
