L34_1 = "현재 보유 중인 <color=#ffcf3b>보상 포인트</color>가\n승리 시 <color=#ffcf3b>획득 할 수 있는 최대 건틀렛 포인트</color> 보다 적습니다.\n\n이대로 계속 진행하시겠습니까?"
