L35_1 = "SI_PF_LEAGUEMATCH_DESC"
L36_1 = "실시간으로 겨루는 대전입니다.\n대전의 금지유닛을 직접 정할 수 있으며,\n중복 유닛이 허용되지 않습니다.\n\n매 주 월요일 오전 4시 주간 챔피언이 선정됩니다. 결산때 최종 성적에 따른 특별한 보상을 얻습니다.\n\n<color=#ffdb6c>장비와 성장으로 증가한 체력, 공격력, 방어력의 10%만 적용됩니다.\n함선 등급에 따라 증가하는 기초 출격자원이 적용되지 않습니다.</color>"
