L34_1 = "비동기로 겨루는 대전입니다.\n전투를 직접 조작하여 대결할 수 있습니다.\n\n매 주 결산과 시즌 결산때 최종 성적에 따른 보상을 얻습니다.\n\n<color=#ffdb6c>장비와 성장으로 증가한 체력, 공격력, 방어력의 10%만 적용됩니다.\n함선 등급에 따라 증가하는 기초 출격자원이 적용되지 않습니다.\nSSR등급의 함선에 최대 피해제한 20% 효과가 추가됩니다.</color>"
