L7_1 = {}
L8_1 = "SI_PF_DEFENCE_BANNER_01_DESC_1"
L9_1 = "아시다시피 프론트베이 앞바다는 오늘도 서로 치고받기 바쁜 해적들 때문에 잔잔할 날이 없습니다. 그럼에도 드넓은 바다로 향하는 것은 뱃사람의 숙명 아닐까요?\n닻을 올리고 출항할 시간이 되었습니다, 선장님! 올해는 검은 범람으로 침식체가 풍어라죠? 앞을 가로막는 건 물살이든 인파든 헤치고, 수면 위에 우리의 이름을 새겨 봅시다! 물거품을 남겨도 후회는 남기지 않도록!"
