L25_1 = {}
L26_1 = "SI_PF_POPUP_EVENT_RACE_BETTING_TUTORIAL"
L27_1 = "<b><color=#4EC2F3>[팀 대항 이어달리기]</color></b>\n<color=#FFCF3B>- 두 팀 중 한 팀을 선택한 다음 이벤트 재화를 이용하여 응원할 수 있습니다.</color>\n<color=#FFCF3B>- 응원한 팀이 승리하였을 경우 보상 배율에 맞춰 이벤트 재화를 획득할 수 있습니다.</color>\n<color=#FFCF3B>- 경주는 매일 1회씩 진행되며, 정산 시간에는 이벤트를 진행하실 수 없습니다.</color>\n\n<b><color=#FFFFFF>[경주 미션]</color></b>\n<color=#F2F2F2>- 제공된 미션을 클리어하여 이벤트 재화를 획득할 수 있습니다.</color>\n\n<b><color=#FFFFFF>[응원]</color></b>\n<color=#F2F2F2>- 이벤트 재화를 사용하여 원하는 팀을 선택해 응원할 수 있습니다.</color>\n<color=#F2F2F2>- 하루 한 팀만 선택 가능합니다.</color>\n<color=#F2F2F2>- 일일 최대 500개까지 응원할 수 있습니다.</color>\n\n<b><color=#FFFFFF>[보상]</color></b>\n<color=#F2F2F2>- 응원한 팀이 승리하였을 경우 응원에 사용한 이벤트 재화가 보상 배율에 맞춰 지급됩니다.</color>\n<color=#F2F2F2>- 응원한 팀이 패배하였을 경우 응원에 사용한 이벤트 재화의 80%를 돌려받습니다.</color>\n<color=#F2F2F2>- 다음날 경기가 시작될 때 참여한 경기의 대한 보상을 획득할 수 있습니다.</color>"
L25_1[1] = L26_1
L25_1[2] = L27_1
