L44_1 = "해당 기능은 GDPR이 적용되는 \n<color=#ffcf3b>EU 국가(EEA 및 영국) 거주자를</color> 대상으로 하는 개인정보 보호법과 관련되어 있습니다.\n(그외 지역과 국가에 거주 중인 경우 영향을 받지 않습니다)\n다시 동의를 하시거나, 동의 철회를 원하시는 경우, 아래의 <color=#ffcf3b>[확인]</color>을 눌러주세요."
